        #[repr(C, packed(4))]
        #[derive(Debug, Copy, Clone, Default)]
        pub struct Compositor_FrameTiming {
            /// Set to sizeof( Compositor_FrameTiming )
            pub m_nSize: u32,
            pub m_nFrameIndex: u32,
            /// number of times this frame was presented
            pub m_nNumFramePresents: u32,
            /// number of times this frame was presented on a vsync other than it was originally predicted to
            pub m_nNumMisPresented: u32,
            /// number of additional times previous frame was scanned out
            pub m_nNumDroppedFrames: u32,
            pub m_nReprojectionFlags: u32,
            /// Absolute time reference for comparing frames.  This aligns with the vsync that running start is relative to.
            pub m_flSystemTimeInSeconds: f64,
            /// time spent rendering the scene (gpu work submitted between WaitGetPoses and second Submit)
            pub m_flPreSubmitGpuMs: f32,
            /// additional time spent rendering by application (e.g. companion window)
            pub m_flPostSubmitGpuMs: f32,
            /// time between work submitted immediately after present (ideally vsync) until the end of compositor submitted work
            pub m_flTotalRenderGpuMs: f32,
            /// time spend performing distortion correction, rendering chaperone, overlays, etc.
            pub m_flCompositorRenderGpuMs: f32,
            /// time spent on cpu submitting the above work for this frame
            pub m_flCompositorRenderCpuMs: f32,
            /// time spent waiting for running start (application could have used this much more time)
            pub m_flCompositorIdleCpuMs: f32,
            /// time between calls to WaitGetPoses
            pub m_flClientFrameIntervalMs: f32,
            /// time blocked on call to present (usually 0.0, but can go long)
            pub m_flPresentCallCpuMs: f32,
            /// time spent spin-waiting for frame index to change (not near-zero indicates wait object failure)
            pub m_flWaitForPresentCpuMs: f32,
            /// time spent in IVRCompositor::Submit (not near-zero indicates driver issue)
            pub m_flSubmitFrameMs: f32,
            /// The following are all relative to this frame's SystemTimeInSeconds
            pub m_flWaitGetPosesCalledMs: f32,
            pub m_flNewPosesReadyMs: f32,
            /// second call to IVRCompositor::Submit
            pub m_flNewFrameReadyMs: f32,
            pub m_flCompositorUpdateStartMs: f32,
            pub m_flCompositorUpdateEndMs: f32,
            pub m_flCompositorRenderStartMs: f32,
            /// pose used by app to render this frame
            pub m_HmdPose: TrackedDevicePose_t,
            pub m_nNumVSyncsReadyForUse: u32,
            pub m_nNumVSyncsToFirstView: u32,
            pub m_flTransferLatencyMs: f32,
        }
